// th15_s2_b6 — TH15 v1.00b Stage 2 BossCard3
// 源: st02bs.ecl.txt:944-1024 (BossCard3), 1026-1134 (BossCard3_at)
// 普通: 月見「セプテンバーフルムーン」; Lunatic: 月見酒「ルナティックセプテンバー」
// 卡帧 0 对应源 timerReset 之后的入口; 开场 120 帧缓冲由外壳承担。

const TIME_LIMIT: int = 3124;     // 120 缓冲 + 3000 源窗口 + 4 启动余量
const OPENING_BUFFER: int = 120;

// 源 etSprite 使用 type1 (E/N/H) 与 type5 (L); 行基址由 TH15 弹型表复用。
const TH15_PELLET2: int = 368;
const TH15_BALL2: int = 432;

// 每条弹的 EX 链 (BossCard3_at 1029-1132):
//   record3 STEP a=1 b=1 c=4: 段界改角 dir、恢复速 0.5
//   record4 VELTIME a=40 r=3.0(E/N/H)/3.8(L), s=-999999 保角
//   record5 STEP a=40 b=1 c=3: 线性降到 0, 段界角恢复 SAVE 的出生角, 速 0.8
//   record6 STEP a=0 b=1 c=5: 段界加 rand[-1,1]*1deg
//   record7 STEP a=0 b=1 c=7: 段界速 += rand[-1,1]*(0.2 E/N/H / 0.3 L), 保角
// 源 SPEEDUP/BRIGHT/ANIM/SAVE 的记录行为分别按无副作用/纯表现/无/局部快照省略。
xformdef MOON(dir: angle, accel: fx, js: fx) {
    @1 set_angle(dir);        // record3 a=1 段界: 全波共享角, 之前 1 帧速 0
    set_speed(0.5fx);         // record3 s=0.5
    @40 set_accel(accel);     // record4 40 帧沿向恒加速到 3.0/3.8
    set_accel(0fx);
    @40 step_speed(0fx, 40);  // record5 a=40: 当前逻辑速线性降到 0
    turn(at_spawn($self_angle - dir));                     // c=3: 恢复该弹出生角
    turn(at_effect(((rand(65536) - 32768) / 182) as angle)); // c=5: ±1deg
    set_speed(at_effect(0.8fx + ((rand(65536) - 32768) as fx / 32768) * js)); // c=7
}

// 源 412 moveRand(30,4,1.0) + 504 moveLimit(0,144,240,64):
// 方向内区 x±60、y128..160，实际限位 x±120、y112..176。
sub move_rand() {
    var a: int = 0;
    var r: int = rand(65536) - 32768;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 128fx {
        if a < 0 { a = -a; }
    } else if $self_y > 160fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    // 速度 1-k/30 (k=1..30), 总位移 14.5; 用 QUAD_OUT 位置插值近似该降速轨迹。
    var dx: fx = $self_x + 14.5fx * cos(a as angle);
    var dy: fx = $self_y + 14.5fx * sin(a as angle);
    if dx < -120fx { dx = -120fx; }
    if dx > 120fx { dx = 120fx; }
    if dy < 112fx { dy = 112fx; }
    if dy > 176fx { dy = 176fx; }
    move_to(30, dx, dy, EASE_QUAD_OUT);
}

// 一次 BossCard3_at: 10 个 %A (40deg 步进) x 7 个 %B 锚点 (2pi/7 步进)。
// 每轮重新配置 record3 的方向; Easy 只发 etOn 为 !* 的 k=0,2,4,6 波。
sub volley() {
    var rank: int = global(GVAR_RANK);
    var shape: int = TH15_PELLET2;
    var ways: int = 16;          // !E 16 / !N 16 / !H 20 / !LO 18
    var accel: fx = 0.0625fx;    // (3.0-0.5)/40
    var js: fx = 0.2fx;          // record7 c7 幅度
    if rank == RANK_HARD {
        ways = 20;
    } else if rank == RANK_LUNATIC {
        ways = 18;
        shape = TH15_BALL2;
        accel = 0.0825fx;        // (3.8-0.5)/40
        js = 0.3fx;
    }
    sh_reset(0);
    sh_sprite(0, shape, 2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_angle(0, 0deg, 0deg);     // 源 etAngle(0, 0.0f, 0.034906585f), layers=1
    sh_speed(0, 0fx, 0fx);       // 源 etSpeed(0,0,1), 单层取 s0=0
    sh_dist(0, 18fx);            // 源 etDist(0,18.0f)
    var dir: int = -16384;       // %A = -pi/2
    for it in 0..10 {            // $D=9, 循环 10 次
        sh_xform(0, MOON(dir as angle, accel, js));
        var b: int = 16384;      // %B = pi/2
        for k in 0..7 {
            // 色序 2,4,6,8,10,13,14（前五波等步长，后两波单独）
            var col: int = 2 + 2 * k;
            if k >= 5 { col = k + 8; }
            if rank != RANK_EASY || k % 2 == 0 {
                sh_sprite(0, shape, col);
                sh_offset_rad(0, b as angle, -32fx);  // 源 etOffsetRad(%B, -32)
                sh_fire(0);
            }
            b = b + 9362;        // 0.897598 rad = 2pi/7
        }
        dir = dir + 7282;        // 0.698132 rad = 40deg
    }
}

async sub boss() {
    set_invuln(65535);
    set_hitbox(24fx);            // 源 setHitbox(48,48) 普通圆第一值*0.5
    set_hurtbox(20fx);           // 源 setHurtbox(40,40)
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);  // 源 movePosTime(60,4,0,144), 起点(0,128)
    wait(124);                   // 源计时 0 -> 124: 首次发射
    loop {
        volley();
        if global(GVAR_RANK) == RANK_LUNATIC {
            wait(360);           // !LO
        } else {
            wait(320);           // !ENH
        }
        move_rand();             // 源 moveRand(30,4,1.0)
        wait(100);               // 源 wait(40) + 下一轮 60 帧前奏
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
